-- ----------------------------
-- Table structure for beautician
-- ----------------------------
DROP TABLE IF EXISTS `beautician`;
CREATE TABLE `beautician`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '美容师编号',
  `job_id` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '工号',
  `name` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '姓名',
  `username` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '账号',
  `password` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '密码',
  `sex` int(11) NULL DEFAULT NULL COMMENT '性别[0:男,1:女]',
  `age` int(11) NULL DEFAULT NULL COMMENT '年龄',
  `avatar` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '头像',
  `info` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '个人简介',
  `status` int(11) NULL DEFAULT NULL COMMENT '当前状态[0:休息,1:空闲,2:服务中]',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `recomment` int(11) NULL DEFAULT NULL COMMENT '首页推荐',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '美容师' ROW_FORMAT = Dynamic;

