-- ----------------------------
-- Table structure for beauty_projects
-- ----------------------------
DROP TABLE IF EXISTS `beauty_projects`;
CREATE TABLE `beauty_projects`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '项目编号',
  `title` varchar(50) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '标题',
  `info` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '简介',
  `price` decimal(10, 2) NULL DEFAULT NULL COMMENT '价格',
  `detail` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '详情',
  `cover_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '封面图片',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态[0:禁用,1:启用]',
  `banner` int(11) NULL DEFAULT NULL COMMENT '首页推荐',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 27 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '美容项目' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of beauty_projects
-- ----------------------------
INSERT INTO `beauty_projects` VALUES (1, '光子嫩肤', '光子嫩肤可显著提亮肤色、有效淡化细纹，紧致缩小毛孔、改善肤质。', 859.00, '#### 工作原理\n光子嫩肤利用的是选择性光热作用原理。不同波长的光可以被皮肤中的不同成分吸收。例如，黑色素、血红蛋白和水分子等都可以吸收特定波长的光。当这些成分吸收光能后，会产生热量，从而破坏或改变其结构，达到治疗目的。\n\n#### 适用人群\n- 肤色不均、有色素沉着的人群\n- 有细纹、皱纹等轻度老化迹象的人群\n- 面部有红血丝、毛细血管扩张的人群\n- 希望改善毛孔粗大问题的人群\n- 想要提亮肤色、增加皮肤光泽度的人群\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n- 咨询与评估：在治疗前，医生会进行详细的皮肤评估，了解患者的皮肤状况和需求，制定个性化的治疗方案。\n- 清洁与准备：治疗前需要彻底清洁面部，并涂抹专用的冷凝胶，以保护皮肤并提高治疗效果。\n- 治疗操作：医生会根据治疗方案选择合适的波长和能量，将光均匀照射在面部或其他治疗区域。每次治疗大约需要20-30分钟。\n- 术后护理：治疗后，医生会提供一些护肤建议，如避免阳光直射、使用温和护肤品等。部分人可能会出现轻微的红肿或灼热感，通常会在几小时内消退。\n\n#### 注意事项\n- 治疗前后应避免暴晒和使用刺激性护肤品。\n- 治疗后可能会有短暂的红肿或斑点加深现象，这是正常的反应，一般会在几天内恢复。\n- 多次治疗可以增强效果，但每次治疗之间需要间隔一段时间。\n- 光子嫩肤是一种安全有效的美容方法，能够帮助改善多种皮肤问题，提升肌肤质量。如果你对自己的皮肤状况不满意，不妨考虑尝试这种非侵入性的美容技术。\n\n\n\n\n', 'http://localhost:8092/file/af1398ab-c533-4607-bddc-e8a2a9e1cff1.png', '2024-11-13 14:53:20', 1, 2);
INSERT INTO `beauty_projects` VALUES (4, '面部护理', '面部护理焕发肌肤光彩，深层清洁与保湿，恢复肌肤水润与弹性。', 150.00, '#### 工作原理\n通过专业的洁面产品和手法，深层清洁肌肤，去除污垢、油脂和老化角质，为肌肤提供清爽的环境；利用护肤品中的营养成分，如维生素、胶原蛋白等，为肌肤提供所需的营养，促进细胞再生和修复；通过按摩等手法，促进血液循环，加速新陈代谢，有助于排出毒素和废物，改善肤色；平衡肌肤的水油平衡，调节肌肤的酸碱度，使肌肤更加健康、稳定。\n\n#### 适用人群\n面部护理适用于以下人群：\n- 皮肤干燥、缺水：肌肤缺乏水分，导致干燥、紧绷、脱皮等现象。\n- 肤色暗沉、色斑：由于紫外线、内分泌等因素导致的肤色暗沉、色斑等问题。\n- 肌肤敏感、易受刺激：肌肤屏障受损，容易受到外界环境的刺激，出现红肿、瘙痒等问题。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n面部护理的治疗过程通常包括以下几个步骤：\n- 清洁：使用温水和洁面产品彻底清洁面部，去除污垢和油脂。\n- 去角质：使用温和的去角质产品去除老化角质，使肌肤更加光滑细腻。\n- 按摩：使用专业的按摩手法和护肤品，促进血液循环，加速新陈代谢。\n- 敷面膜：根据肌肤状况选择合适的面膜，进行深层滋养和修复。\n保湿：使用保湿乳液或面霜，为肌肤提供持久的保湿效果。\n\n#### 注意事项\n在进行面部护理时，需要注意以下事项：\n- 选择正规机构：确保选择正规的医疗机构或美容机构进行面部护理，避免受到不良产品的侵害。\n- 了解自身肤质：在进行面部护理前，要了解自己的肤质和需求，选择适合自己的护理项目和产品。\n- 避免过度清洁：不要过度清洁面部，以免破坏肌肤屏障，导致肌肤敏感和干燥。\n- 注意饮食健康：保持健康的饮食习惯，多摄入富含维生素和蛋白质的食物，有助于肌肤的健康和修复。\n- 防晒：在进行面部护理后，要注意防晒，避免紫外线对肌肤的伤害。\n- 避免刺激：避免使用含有刺激性成分的护肤品，以免刺激肌肤导致不适。\n', 'http://localhost:8092/file/37b23ca9-e2bc-495b-af1f-0c6db009d398.png', '2024-11-13 07:06:23', 1, NULL);
INSERT INTO `beauty_projects` VALUES (5, '水光', '水光可保湿锁水、美白嫩肤、紧致提升、祛痘杀菌并淡化皱纹。', 500.00, '#### 工作原理\n水光针的原理是通过皮肤微创注射技术，将透明质酸等保湿成分及其他活性物质注射到皮肤真皮层，利用这些成分在皮肤内形成保湿层，锁住水分，同时激活皮肤自我修复机制，促进胶原蛋白和弹力纤维的生成，从而改善皮肤干燥、缺水、肤色不均、细纹等问题，使皮肤变得水润、光泽、有弹性。\n#### 适用人群\n水光针适用于18岁以上到60岁以下的人群，特别是以下情况：\n- 皮肤干燥、缺水，看起来显老的人。\n- 气色不好，为皮肤不化妆就没有朝气而烦恼的人。\n- 平时不容易上妆的干性皮肤人。\n- 极度缺水皮肤，即使用高价格的补水乳液也没办法改善皮肤干燥的人。\n- 肌肤已经老化或希望预防肌肤老化的人。\n- 肌肤受到光损害的人。\n然而，以下人群则不适合水光针：\n- 过敏体质或对水光针成分过敏的人。\n- 面部有明显发炎或皮肤有传染性疾病者。\n- 短时间内做过微整手术，面部还未得到修复的人。\n- 生病或哺乳期的人。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n水光针的治疗过程通常包括以下几个步骤：\n- 清洁面部：使用温和的清洁剂彻底清洁面部，确保皮肤无油脂污垢。\n- 消毒：使用含有酒精或其他消毒成分的溶液对面部进行全面消毒，以避免感染。\n- 涂抹表面麻醉剂：在治疗区域涂抹表面麻醉剂，一般需要等待20~30分钟以减少痛感。\n- 配制注射液：根据个体皮肤状况，配制适量的透明质酸等注射液。\n- 调整注射器：选择合适的水光针注射器，并调节好注射深度和剂量。\n- 注射：通过多点注射技术，将配制好的注射液均匀注入皮肤的真皮层。注射过程一般持续20~30分钟。\n- 冷敷：注射结束后进行冷敷，可以有效减轻红肿和疼痛。\n\n#### 注意事项\n请注意，水光针的效果因个体差异而异，且可能存在一定的风险和副作用。在进行水光针治疗时，务必选择正规的医疗机构，由专业医生进行操作，并严格遵循术前和术后的注意事项，以确保治疗的安全和效果。\n- 术后护理：注射水光针后，施术部位要保持干净，不能过分按摩揉捏，要注意防晒。建议在24小时内避免沾水，避免挤压脸部，避免脸部暴晒，避免剧烈运动，避免接触刺激性物质，避免化妆。72小时之后再进行洗脸、护肤等，避免使用刺激性护肤品，洗脸注意要轻柔。\n- 生活习惯：在饮食上，要注意多吃富含维生素的水果和富含膳食纤维的蔬菜，避免抽烟、饮酒，以及吃辛辣刺激和生冷油腻的食物。保持一个健康的生活习惯。\n- 避开特殊时期：打水光针要避开月经期，以免导致局部出现感染的情况。\n- 保暖：水光针属于一种注射类的护肤疗法，注射后局部的皮肤比较娇嫩，因此应做好相关的防护措施，以免出现着凉的情况。\n\n\n', 'http://localhost:8092/file/9fff5db2-6c7b-47a4-a120-cfa7ec1816b0.jpg', '2024-11-13 07:06:23', 1, 2);
INSERT INTO `beauty_projects` VALUES (7, '点阵激光', '点阵激光可淡化色斑痘痕，紧致肌肤，祛疤除痕，祛斑祛痣，改善毛孔粗大和光老化。', 180.00, '#### 工作原理\n点阵激光是一种基于局灶性光热作用原理的医美方法。它使用特定的波长激光照射皮肤，能够在皮肤组织中产生许多微治疗孔，这一过程不仅有助于分解色素细胞，达到祛斑的效果，还能刺激皮下胶原蛋白和弹性纤维的再生，进而达到紧致皮肤、减少细小皱纹的目的。\n\n#### 适用人群\n点阵激光适用于以下人群：\n- 有青春痘印、黄褐斑、毛孔粗大、痤疮和痘疤痘印等皮肤问题的人。\n- 有眼角皱纹、细纹、脸部及额部皱褶、骨节褶皱及妊娠纹者。\n有雀斑、颧骨母斑等色素性变病者。\n- 有皮肤松弛及深层次疤痕者，希望通过治疗改善肤质和外观。\n请注意，以下人群不适合接受点阵激光治疗：\n- 疤痕体质者。\n- 严重糖尿病、高血压患者。\n- 精神疾病患者，或对治疗效果有过高期待者。\n- 处于活跃期的白癜风、银屑病或针对性红斑狼疮患者。\n- 怀孕期或哺乳期间的女性。\n- 光过敏症状者。\n- 曾行有机化学剥落术、切削术以及其它焕肤术的患者。\n- 应用维甲酸药品者。\n- 不愿意术后进行防晒隔离，及接纳切削术风险的患者。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n点阵激光的治疗过程通常包括以下几个步骤：\n- 医生评估：患者就诊后，医生会根据患者的具体情况进行评估，并制定个性化的治疗计划。\n- 清洁与麻醉：患者需要彻底清洁治疗部位的皮肤，并涂抹麻醉药物，以减轻治疗时的疼痛感。如果疼痛承受能力强，也可以不用打麻醉药。\n- 激光治疗：医生根据治疗计划，通过计算机控制激光器进行点阵激光治疗。激光器会发射出细小的激光束，均匀地打在需要治疗的皮肤上，形成一系列的“点”。这些微治疗孔会促进皮肤组织的修复和再生。\n- 后续处理：治疗结束后，医生会用消毒棉球或纱布轻轻按压治疗部位，以清除多余的血液和液体。治疗部位需要进行适当的保护，通常会涂抹一些保护性的药膏或护肤品。\n\n#### 注意事项\n在接受点阵激光治疗时，患者需要注意以下事项：\n- 治疗前准备：治疗前应避免使用含有化学成分的护肤品，避免对皮肤产生刺激。同时，要保持良好的作息和饮食习惯，以提高皮肤的自我修复能力。\n- 治疗间隔：两次治疗之间必须间隔一段时间，通常建议半个月以上。这是因为点阵激光治疗会对皮肤产生轻微的损伤，需要一定的时间来恢复。\n- 治疗后护理：治疗后，皮肤可能会出现红肿、灼热感等正常现象。此时，可以使用冰袋进行局部冰敷处理，以减轻肿胀与疼痛。同时，要保持治疗部位的清洁和干燥，避免沾水以防止感染。\n- 防晒与保湿：治疗后，皮肤对紫外线的敏感度会增加。因此，在户外活动时，务必做好防晒工作，避免阳光直射。此外，要加强皮肤的保湿工作，使用温和的保湿产品来维护皮肤的水分平衡。\n- 避免刺激：治疗后，要避免使用含有酒精、香料等刺激性成分的化妆品和护肤品。同时，要避免用手触摸或搔抓治疗部位，以防止细菌感染。', 'http://localhost:8092/file/8b0e20c0-3099-424c-982e-a25de3602642.png', '2024-11-13 07:06:23', 1, NULL);
INSERT INTO `beauty_projects` VALUES (8, '唇部护理', '唇部护理能滋润保湿，淡化唇纹，丰盈双唇，提升唇部色泽，焕发健康光彩。', 120.00, '#### 工作原理\n唇部护理的主要工作原理是通过为唇部提供必要的水分和营养，增强唇部的保湿能力，同时去除唇部废旧角质，改善唇部血液循环，从而达到滋润保湿、淡化唇纹、丰盈双唇、提升唇部色泽的效果。\n\n#### 适用人群\n唇部护理适用于以下人群：\n- 唇部干燥、缺水、容易脱皮的人群。\n- 唇纹较深、唇部色泽暗淡的人群。\n- 长期使用口红、唇彩等化妆品，需要定期卸妆和保养的人群。\n唇部皮肤敏感、易受损的人群。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n唇部护理的治疗过程通常包括以下几个步骤：\n- 清洁唇部：使用温和的唇部清洁产品或清水，彻底清洁唇部，去除口红、食物残渣等污垢。\n- 去角质：使用唇部专用的去角质产品，轻柔地去除唇部废旧角质，使唇部更加光滑细腻。\n- 保湿滋润：涂抹具有保湿滋润效果的唇膏、唇膜或唇油等产品，为唇部提供必要的水分和营养，增强唇部的保湿能力。\n- 按摩唇部：轻轻按摩唇部，促进血液循环，有助于改善唇部色泽和淡化唇纹。\n- 防晒保护：在白天外出时，涂抹具有防晒效果的唇膏或唇油，避免唇部受到紫外线的伤害。\n\n#### 注意事项\n在进行唇部护理时，需要注意以下事项：\n- 选择温和的产品：选择温和无刺激的唇部护理产品，避免使用含有刺激性成分的产品，以免对唇部皮肤造成损伤。\n- 避免过度清洁：不要过度清洁唇部，以免破坏唇部皮肤的天然屏障，导致唇部更加干燥。\n- 不要撕扯死皮：避免撕扯唇部死皮，以免损伤唇部皮肤，导致唇部出血或感染。\n- 定期护理：定期进行唇部护理，保持唇部的湿润和光泽。\n- 注意饮食和生活习惯：多喝水，保持身体的水分平衡；避免长时间暴露在干燥的环境中；不要频繁舔唇或咬唇，以免加重唇部干燥。', 'http://localhost:8092/file/395ba518-5635-430a-9ae0-d682b6e26784.png', '2024-11-13 07:06:23', 1, 2);
INSERT INTO `beauty_projects` VALUES (11, '指甲护理', '指甲护理能增强甲床韧性，预防断裂，提亮色泽，使指甲更健康、光滑、亮丽。', 80.00, '#### 工作原理\n指甲护理的主要工作原理是通过为指甲提供必要的营养和滋润，增强甲床的韧性，改善指甲的质地和色泽，从而达到预防指甲断裂、使指甲更健康、光滑、亮丽的效果。指甲护理还可以有效预防指甲周围的皮肤感染和炎症，保持指甲的整体健康。\n\n#### 适用人群\n指甲护理适用于以下人群：\n- 指甲脆弱、易断裂的人群。\n- 指甲色泽暗淡、缺乏光泽的人群。\n- 指甲周围皮肤干燥、易发炎的人群。\n- 经常做美甲、需要定期护理指甲的人群。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n指甲护理的治疗过程通常包括以下几个步骤：\n- 清洁：定期清理指甲缝隙，避免细菌和污垢聚集。同时，保持指甲周围皮肤的清洁干燥。\n- 修剪：使用指甲钳或指甲刀修剪指甲，保持指甲的整洁和美观。修剪时避免将指甲剪得过短，以免导致指甲裂开或变形。\n- 营养滋润：涂抹指甲营养油或强甲油，为指甲提供必要的营养和滋润。这些产品通常含有维生素E、蛋白质等营养成分，有助于增强指甲的韧性和光泽。\n- 按摩：轻轻按摩指甲周围的皮肤，促进血液循环，有助于改善指甲的色泽和质地。\n- 保护：避免使用指甲钳挑出指甲下面的污垢，以免导致指甲松动。同时，避免长时间将指甲浸泡在水中，特别是热水，以免指甲变软和变形。\n\n#### 注意事项\n在进行指甲护理时，需要注意以下事项：\n- 选择合适的产品：选择温和无刺激的指甲护理产品，避免使用含有刺激性成分的产品，以免对指甲和周围皮肤造成损伤。\n- 避免过度修剪：不要将指甲剪得太短，以免导致指甲裂开或变形。同时，避免过度打磨指甲，以免损伤指甲表面和甲床。\n- 保持干燥：保持指甲和周围皮肤的干燥，避免长时间浸泡在水中。洗完手后应及时擦干，避免指甲和指尖潮湿。\n- 营养均衡：良好的饮食习惯对指甲也很重要。吃一些富含维生素和矿物质的食物，如蛋白质、铁、锌、钙和维生素E等，可以帮助加强指甲结构和生长。\n- 避免频繁美甲：虽然美甲可以增加指甲的美观度，但频繁美甲会对指甲造成损伤。建议减少美甲的次数，并定期进行指甲护理以恢复指甲的健康状态。', 'http://localhost:8092/file/ae168bbe-a754-41ba-abea-06b1f68d2610.png', '2024-11-13 07:06:23', 1, NULL);
INSERT INTO `beauty_projects` VALUES (12, '身体护理', '身体护理能深层滋养肌肤，保湿锁水，提升弹性，使全身肌肤柔滑细腻。', 220.00, '#### 工作原理\n身体护理的主要工作原理是通过各种护理方法（如运动、饮食、按摩、使用护肤品等）促进身体的血液循环、淋巴循环和新陈代谢，为肌肤提供必要的营养和滋润，从而增强皮肤的屏障功能，保湿锁水，提升皮肤的弹性和光泽，使全身肌肤变得柔滑细腻。\n\n#### 适用人群\n身体护理适用于以下人群：\n- 皮肤干燥、缺水、粗糙、暗沉的人群。\n- 肌肤缺乏弹性、松弛下垂的人群。\n- 希望改善身体肌肤状态、提升肌肤光泽度和细腻度的人群。\n- 长时间处于空调环境、皮肤容易干燥的人群。\n- 运动员、舞者等需要经常进行身体活动的人群，以保持皮肤状态。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n身体护理的治疗过程通常包括以下几个步骤：\n- 清洁：使用温和的清洁产品彻底清洁全身皮肤，去除污垢和油脂，为后续护理做好准备。\n- 去角质：使用身体磨砂膏或去角质产品去除身体表面的废旧角质，促进后续护肤品的吸收。\n- 滋润保湿：涂抹身体乳液、身体霜等保湿产品，为皮肤提供必要的水分和营养，增强皮肤的保湿能力。\n- 按摩：通过专业的按摩手法对身体进行按摩，促进血液循环和淋巴循环，有助于缓解肌肉疲劳、改善皮肤状态。\n- 营养补充：根据皮肤状况和需求，可以涂抹含有特定营养成分的护肤品，如维生素E、胶原蛋白等，以改善皮肤质地和光泽度。\n\n#### 注意事项\n在进行身体护理时，需要注意以下事项：\n- 选择合适的产品：选择适合自己肤质和需求的产品，避免使用含有刺激性成分的产品，以免对皮肤造成损伤。\n- 保持皮肤清洁：在进行身体护理前，要确保皮肤处于清洁状态，避免污垢和油脂影响护理效果。\n- 适度按摩：按摩时要适度用力，避免过度按摩导致皮肤受损。同时，要根据自己的身体状况和舒适度进行调整。\n- 注意保湿：保湿是身体护理的重要一环，要定期涂抹保湿产品，以保持皮肤的水分平衡。\n- 避免过度清洁：不要过度清洁皮肤，以免破坏皮肤的天然屏障功能，导致皮肤更加干燥和敏感。\n- 饮食和生活习惯：保持良好的饮食习惯和生活习惯，如多喝水、多吃富含维生素和矿物质的食物、保持充足的睡眠等，有助于改善皮肤状态和提升身体护理效果。', 'http://localhost:8092/file/fdc794e4-9b11-4b63-962d-e2dc0ac1904d.png', '2024-11-13 07:06:23', 1, NULL);
INSERT INTO `beauty_projects` VALUES (13, '热玛吉', '热玛吉可紧致肌肤，淡化皱纹，提升轮廓，焕发青春活力，安全无创，效果显著。', 1900.00, '#### 工作原理\n热玛吉的工作原理是利用高能量、高频率的E波进行单极射频传导。通过治疗探头，每秒可以发出高达600万次的振动能量波，这些能量波能够穿透皮肤表层，直达筋膜层，刺激皮肤内部的胶原蛋白收缩，并促进胶原蛋白的再生和重组。这一过程可以使松弛的皮肤变得紧致，从而达到除皱、提拉和紧致肌肤的效果。\n\n#### 适用人群\n热玛吉适用于以下人群：\n- 皮肤松弛、有细纹或皱纹的人群，尤其是面部、颈部和手部等区域。\n- 想要改善皮肤质地、提升皮肤光泽度和弹性的人群。\n- 希望通过非手术方式达到抗衰老效果的人群。\n- 对护肤品和家用抗衰仪器效果不满意，寻求更显著改善的人群。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n热玛吉的治疗过程通常包括以下几个步骤：\n- 清洁皮肤：使用专业的洁面产品彻底清洁皮肤，去除油脂和污垢。\n- 定位打格：使用热玛吉专用的定位打格纸，在患者脸上印出格子，以便全方面、均衡地定位施打。\n- 仪器调试：取出热玛吉专用治疗头，进行仪器调试，确保设备正常运行。\n- 治疗操作：医师将治疗头安装在设备上，开始进行治疗。在治疗过程中，患者会感受到一股短暂的受热感，这表示胶原蛋白已受热刺激，皮肤开始紧致。同时，需要使用热玛吉专用的耦合剂帮助射频准确施打。\n- 完成治疗：整个治疗过程通常需要1~2小时，完成后即可离开。\n\n#### 注意事项\n在进行热玛吉治疗时，需要注意以下事项：\n- 术前准备：治疗前一周内避免去角质和过度按摩皮肤。治疗当天不要化妆，保持皮肤清洁干燥。\n- 避免金属物品：术前在身上不可以佩戴任何的金属物品，如有心脏病或装有心率调整器的人群不建议进行治疗。\n- 术后护理：治疗后，皮肤可能会出现轻微的红肿和灼热感，这是正常现象。应避免用热水洗脸，保持脸部湿度，并加强防晒措施。在一周内至少敷三次面膜，以补充水分和营养。\n- 饮食调整：术后一个月内，建议合理安排饮食，避免辛辣刺激性食物，多吃富含胶原蛋白和维生素的食物，如猪蹄、鱼皮、新鲜水果和蔬菜等。\n- 避免其他美容项目：术后一个月内，不要去美容院进行按摩肌肤、护理面部等美容项目。\n- 定期复诊：为了保持治疗效果，建议定期进行复诊和巩固治疗。', 'http://localhost:8092/file/882fa2da-c69f-4096-9914-bf1afc40afac.jpg', '2024-11-13 07:06:23', 1, 2);
INSERT INTO `beauty_projects` VALUES (14, '黄金微针', '黄金微可紧致肌肤、淡化皱纹、收缩毛孔、提亮肤色，改善皮肤质地。', 200.00, '#### 工作原理\n黄金微针的工作原理是通过双极射频技术和微针技术相结合，利用矩形排列的微针刺入皮肤真皮层，释放射频能量。射频能量产生的热效应可以刺激胶原蛋白的合成和再生，同时促进胶原纤维和弹力纤维的收缩，从而改善皮肤肤质，达到抗衰老和提升面部肌肤的效果。\n\n#### 适用人群\n黄金微针主要适用于以下人群：\n- 早期衰老者：年龄在35~45岁之间，皮肤出现轻度松弛和皱纹。\n- 油性皮肤者：希望改善皮肤油脂分泌过多状况，达到控油效果。\n- 痤疮患者：需要治疗痤疮急性炎症等皮肤问题。\n- 皮肤松弛者：有改善皮肤松弛需求的人群。\n- 皮肤腺体分泌旺盛者：希望抑制部分皮肤腺体分泌的人群。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n黄金微针的治疗过程通常包括以下几个步骤：\n- 清洁面部：使用专业的洁面产品彻底清洁皮肤，去除油脂和污垢。\n- 涂抹麻药：在操作部位均匀涂抹表麻膏，并覆盖保鲜膜以防止麻药挥发。敷麻药的时间通常为30分钟。\n- 消毒清洁：清除敷的表麻膏后，用带有酒精的纱布对操作部位进行消毒和清洁。\n- 开启仪器：人体平躺于治疗床，面部朝上，准备工作完毕后，开启黄金微针射频仪器。\n- 射频操作：操作者手握治疗手柄，对治疗部位进行均匀的射频操作。\n- 术后护理：操作完毕后，给受治疗者敷上医用冷敷贴，以减轻皮肤可能出现的灼热感和红肿。冷敷时间通常为15分钟。\n\n#### 注意事项\n在进行黄金微针治疗时，需要注意以下事项：\n- 术前准备：治疗前应避免使用含有酒精或其他刺激性成分的护肤品，同时避免进行皮肤磨削等美容项目。\n- 专业评估：选择专业医疗机构和经验丰富的医生进行治疗，并在治疗前进行详细的皮肤评估。\n- 术后护理：治疗后，皮肤可能会出现轻微的红肿和灼热感，这是正常现象。应避免用热水洗脸，保持脸部湿度，并加强防晒措施。术后一周内不可吃辛辣、刺激性食物及易发食物，忌烟、忌酒，以促进皮肤恢复。\n- 避免高温环境：在治疗后一个月内，避免去高温环境，如温泉、桑拿、高温瑜伽等，并避免暴晒。\n- 定期复诊：为了保持治疗效果，建议定期进行复诊和巩固治疗。\n- 避免剧烈运动：术后要保持局部干燥整洁，不要做剧烈运动，避免出汗引起局部感染。', 'http://localhost:8092/file/3a170efa-c4ec-485e-89bc-05e560004660.jpg', '2024-11-13 07:06:23', 1, 2);
INSERT INTO `beauty_projects` VALUES (15, '眉形设计', '精致眉形，提升气质，彰显个性，自然和谐，让脸部更立体，美丽加分，自信倍增。', 300.00, '#### 工作原理\n眉形设计是根据顾客的面部骨骼、肌肉走势、五官比例、气质等因素，结合美学原理，为顾客量身定制适合的眉形。通过专业的手法和技巧，使眉毛的形状、颜色和韵味与顾客的整体形象相协调，从而达到提升面部美感的效果。\n\n#### 适用人群\n眉形设计适用于所有希望改善眉毛形状、提升面部美感的人群。特别是眉毛稀疏、眉形不佳、眉毛颜色不均或眉毛有缺陷的人群，通过眉形设计可以得到显著改善。此外，对于追求完美、希望提升个人形象气质的人群，眉形设计也是一个不错的选择。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n眉形设计的治疗过程主要包括以下几个步骤：\n- 沟通与咨询：纹绣师与顾客进行充分沟通，了解顾客的期望和需求，同时评估顾客的面部特征和气质，以确定适合的眉形。\n- 设计眉形：根据顾客的面部特征、五官比例和气质，纹绣师使用专业的眉笔或眉粉为顾客设计眉形。设计过程中，纹绣师会不断调整和优化眉形，直到达到顾客满意的效果。\n- 实施操作：设计完成后，纹绣师会使用专业的纹眉工具和技术，将眉毛部位的皮肤刺破，让颜料渗入到皮下，以形成持久的眉形。操作过程中，纹绣师会注意手法和力度的控制，以确保操作的安全和效果。\n- 术后护理：操作完成后，纹绣师会向顾客提供详细的术后护理指导，包括保持伤口清洁干燥、避免剧烈运动和接触刺激性物质等。同时，纹绣师还会定期回访顾客，了解恢复情况并提供必要的帮助。\n\n#### 注意事项\n- 选择专业机构：进行眉形设计时，应选择具有合法资质和丰富经验的专业机构，以确保操作的安全和效果。\n- 术前准备：术前应避免饮酒和服用影响凝血功能的药物，同时保持面部清洁和干燥，避免化妆和涂抹护肤品。\n- 术后护理：术后应遵循纹绣师的指导进行护理，避免剧烈运动和接触刺激性物质，以免影响恢复和效果。\n- 饮食注意：术后应避免食用辛辣、刺激性食物和海鲜等发物，以免引发过敏反应或影响恢复。\n- 定期回访：术后应定期回访纹绣师，了解恢复情况并提供必要的帮助和指导。', 'http://localhost:8092/file/b15a63b7-6053-4192-aa76-67aa6db43ad2.png', '2024-11-13 07:06:23', 1, 2);
INSERT INTO `beauty_projects` VALUES (18, '身体按摩', '身体按摩舒缓肌肉，促进血液循环，缓解疲劳，提升身体活力，促进身心健康。', 250.00, '#### 工作原理\n身体按摩的工作原理主要基于神经传导和血液循环的调节。通过对手法、力度和技巧的运用，按摩师可以对身体的各个部位进行按压、摩擦和推拿，从而刺激局部神经末梢和肌肉组织。这种刺激能够引发一系列神经传导反应，最终传递到大脑皮层，使大脑对疼痛部位产生相应的生理反应，缓解疼痛和紧张感。同时，按摩还能促进血液循环，增加受损组织的营养供应，进一步促进身体的恢复和放松。\n\n#### 适用人群\n身体按摩适用于以下人群：\n- 肌肉僵硬酸痛、扭伤、关节脱位或关节疼痛的人群。\n- 脾胃虚弱、失眠、神经衰弱、习惯性便秘等中医病症的患者。\n- 需要缓解压力、焦虑和改善睡眠质量的人群。\n- 免疫力较弱或内分泌失调的人群，希望通过按摩来增强免疫力和调节内分泌。\n\n然而，需要注意的是，有开放性创伤、急性传染病、严重心血管病或身体比较虚弱、年龄较大的患者不适合进行按摩。\n\n![1aa7560496dd48fb921cb8be24d22c43.png](http://localhost:8092/file/5b8436d2-d4f6-493f-8f09-d2f4d87f9c44.png)\n\n#### 治疗过程\n- 准备工作：将按摩区域暴露出来，换上舒适宽松的衣服或直接裸露皮肤（注意隐私保护），保证按摩环境安静、温度适宜。\n- 热身：轻轻按摩身体表面，帮助肌肉和组织放松。可以使用手掌、拳头、指尖等不同的部位进行按摩，力度适中，避免过度刺激。\n- 深层按摩：针对具体部位进行深层按摩。可以使用揉捏法、推拿法等多种手法，以圆形运动揉捏肌肉或向一个方向推动。\n- 伸展：通过拉伸肢体和关节来促进身体的柔韧性和灵活性。可以给身体某个部位施加轻微的压力并缓慢地使其弯曲和伸展。\n- 肌肉放松：在整个按摩结束时，使用轻柔的手法平抚和按摩身体表面，以帮助肌肉松弛和紧张情绪缓解。\n\n#### 注意事项\n在进行身体按摩时，需要注意以下几点：\n- 选择专业按摩师：确保按摩师具备专业的技能和资质，避免因操作不当而对身体造成伤害。\n- 避免过度按摩：按摩时间不宜过长，一个部位最长20分钟，否则可能适得其反。同时，按摩力度也要适中，避免过度用力造成损伤。\n- 注意身体状况：在饥饿状态、刚吃饱或酗酒、过度疲劳时不宜进行按摩。此外，有严重疾病或身体不适的人群应在医生指导下进行按摩。\n- 保持放松：在按摩过程中保持身心放松，不要浑身僵硬。如果感到疼痛或不适，应立即与按摩师沟通并调整手法。\n- 保暖和休息：按摩后要注意保暖，避免受风、受凉。同时，适当休息几分钟再下地活动，让身体逐渐适应。', 'http://localhost:8092/file/699e2c79-b315-49f9-a213-df3c3163f0cf.png', '2024-11-13 07:06:23', 1, NULL);
INSERT INTO `beauty_projects` VALUES (23, '牙齿美白', '牙齿美白可使牙齿更加洁白、亮丽，去除牙渍，让牙齿恢复自然亮白光泽。', 400.00, '11', 'http://localhost:8092/file/d88d6778-beec-4b18-9e98-d4dd62592e19.png', '2024-12-03 23:35:18', 1, 2);
INSERT INTO `beauty_projects` VALUES (24, 'SPA水疗', 'SPA水疗舒缓身心，促进血液循环，缓解疲劳，增强免疫力，焕发肌肤活力。', 500.00, '11', 'http://localhost:8092/file/27fbf852-3923-4ba1-9729-80d4beecfa31.png', '2024-12-03 23:37:38', 1, NULL);
INSERT INTO `beauty_projects` VALUES (25, '头发护理', '头发护理是一个细致且全面的过程，需要一系列专业的护发产品和正确的护理方法。', 200.00, '11', 'http://localhost:8092/file/32e4bff1-71bf-4c6a-ab92-efe50403feca.png', '2024-12-03 23:39:16', 1, 2);
INSERT INTO `beauty_projects` VALUES (26, '激光脱毛', '激光脱毛安全高效，长久减少毛发，肌肤光滑细腻，实现长久性脱毛。', 300.10, '11', 'http://localhost:8092/file/bffa7b97-3450-42d8-a63b-238bb7675d01.jpg', '2024-12-04 11:43:19', 1, NULL);

-- ----------------------------
-- Table structure for evaluate
-- ----------------------------
DROP TABLE IF EXISTS `evaluate`;
CREATE TABLE `evaluate`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '评价编号',
  `order_id` bigint(20) NULL DEFAULT NULL COMMENT '订单编号',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目编号',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户编号',
  `content` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '评价内容',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '评价时间',
  `info` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '回复',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '订单评价' ROW_FORMAT = Dynamic;

