-- ----------------------------
-- Table structure for news
-- ----------------------------
DROP TABLE IF EXISTS `news`;
CREATE TABLE `news`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '资讯编号',
  `title` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '资讯标题',
  `cover_img` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '封面图片',
  `content` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '资讯简介',
  `detail` text CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '详细内容',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态[0:禁用,1:启用]',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '发布时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 573 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '新闻资讯' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of news
-- ----------------------------
INSERT INTO `news` VALUES (569, '光子嫩肤', 'http://localhost:8092/file/dd445466-1abf-4426-a0a1-46b3bef8c3dc.png', '采用特定的宽光谱彩光，直接照射于皮肤表面，嫩肤、去皱、去色素。', '## 基础信息\n**项目优点**\n-  副作用相对较少、恢复期也较短; \n- 针对性调节色素斑、毛孔粗大、面色晦暗、细小皱纹、肌肤粗糙、痤疮等皮肤问题，并协同作用于收缩毛孔，紧致皮肤。\n\n**项目缺点**\n- 治疗周期长，需多次治疗。\n\n**禁忌人群**\n-  妊娠期女性;\n- 光过敏者、对光敏感者及用过光敏感药物者;\n- 高血压、糖尿病患者;\n-  长期服用某些精神类药物者;\n-  服用消炎药、降压药者;\n-  两周内有日光曝晒者;7.面部有炎症者。\n\n**适用人群**\n- 适用于毛孔粗大、肤色不均、有色斑、痤疮、痘印和红血丝等皮肤问题的人群。\n\n## 使用方式\n|操作时间|恢复时间|间隔周期|\n|-|-|-|\n|10-20分钟|0-7天左右|3-6次，每次间隔1个月|\n|作用周期|操作方式|麻醉方式|\n|1-2个月|光电|无需麻醉|\n\n## 术后及常见问题\n==术前准备==\n- **护理方法：**\n治疗前一周，不能做激光、皮肤磨削术、果酸焕肤等美容项目;近期接受过暴晒者，在治疗前需向医生说明:治疗前清洁面部，不能残留化妆品。\n\n==0天~3天 红肿期==\n- **护理方法：**\n治疗后，可以使用胶原面贴敷料或冰膜;多补充维生素C，注意皮肤保湿，严格防晒，用冷水洗脸，禁烟酒及辛辣刺激的食物。\n- **恢复提示：**\n皮肤会有粗糙感，一般可在当天或隔日逐渐消失;个别患者可能会出现，短暂的红肿热等反应\n- **正常情况：** \n-泛红，结痂，变白，肤色提亮，透亮，灼热，自然，红肿，紧致，微疼，变嫩，变干\n- **异常情况：**\n过敏，水泡，疼痛难忍，流血，坑坑洼洼，色脱，蜕皮，发黑，黑色素沉着，灼伤\n\n==4~7天 结痂期==\n- **护理方法：**\n禁烟酒、辛辣刺激性食物，及颜色深的食物如:咖啡、可乐等:不参加激烈运动，避免出汗后引起感染;面部治疗后5天内，不宜用热水洗脸，擦干治疗部位后，薄薄地涂上药膏，直至痂皮脱落不可使用，其他药物或化妆品;避免日晒，尽量使用防晒或打伞，室内室外都需涂抹防晒产品，避免晒伤导致色素沉着\n- **恢复提示：**\n皮肤红肿基本消退，局部色素加深，皮肤表面出现无创性薄痂。\n- **正常情况：**\n透亮，泛红，脱落，结痂，补水，脱皮，自然，色斑，白净，细致，皮肤于燥\n- **异常情况：**\n结疤，色素沉着，过敏，水泡，疼痛难忍，流血，坑坑洼洼，色脱，蜕皮，发黑。\n\n==++8~15天 结痂脱落期++==\n- **护理方法：**\n继续使用修复产品，严格注意防晒，避免晒伤导致色素沉着:做好保湿工作，干痒严禁搔抓，要让痂皮自行成熟脱落，不得强行剥落。\n- **恢复提示：**\n痂皮逐渐脱落完毕，形成新生皮肤，呈淡粉色。\n- **正常情况：**\n结痂脱落，变白，透亮，毛孔缩小，细致，变亮，紧致，肤色提亮，红血丝，紧致。\n- **异常情况：**\n过敏，水泡，疼痛难忍，流血，坑坑洼洼，色脱，蜕皮，发黑，黑色素沉着，灼伤。\n\n==++效果显现期16天~30天++==\n- **护理方法：**\n注意防晒和保湿，如想彻底祛除斑点，可以通过疗程治疗;术后如有任何不良反应，请及时到院复诊。\n- **恢复提示：**\n术后反应消退，效果逐渐显现，肤色提亮，色斑改善。\n- **正常情况：**\n色斑脱落，掉痂，变嫩，自然，白净，变亮，紧致，肤色提亮，毛孔缩小，肤质细致。\n- **异常情况：**\n不适感，敏感，不均匀，蜕皮，过敏，水泡，疼痛难忍，流血，坑坑洼洼，色脱。\n', 1, '2024-12-05 18:29:21');
INSERT INTO `news` VALUES (570, '深圳2025年眼部下睑松弛矫正专业医院TOP3榜单揭晓！', 'http://localhost:8092/file/98a58af5-d514-47a8-955f-e4784ff3d98e.png', '深圳眼部下脸松弛矫正排名前三医院揭晓!', '深圳眼部下脸松弛矫正排名前三医院揭晓!新榜单更新，为您呈现深圳地区**的五家医院。这些医院包括深圳南山区人民医院整形美容科、深圳美菜医疗美容医院、深圳壹号美都医疗美容门诊部、深圳天丽医疗美容门诊部以及深圳鹏爱悦已医疗美容门诊部等。这份榜单是根据用户的消费行为习惯以及客户咨询反馈等多项核心数据生成的，排名不分先后。\n\n![98a58af5d51447a8955fe4784ff3d98e.png](http://localhost:8092/file/505f7a1b-d37d-463c-aa57-8eaea9130bdb.png)\n\n接下来，让我们一起详细了解这三家医院:\n一、深圳南山区人民医院整形美容科\n深圳市南山区人民医院(深圳市第六人民医院)位于深圳经济特区西部南头半岛中心区，是深圳市第四家三级甲等医院也是南山区区域医疗中心。该医院自1946年成立以来，经过多次更名和发展，现已成为一所集医疗、教学、科研、预防保健于一体的现代化医院。其整形美容科作为医院的重点科室之一，拥有先进的诊疗设备和专业的医疗团队，为患者提供意品质的医疗服务。\n\n二、深圳美莱医疗美容医院\n深圳美莱医疗美容医院位于广东省深圳市福田区深南中路，是一家专业的医疗美容机构。该医院拥有先进的医疗美容设备和专业的医疗团队，为患者提供双眼皮手术、鼻部手术、面部手术等美容服务。该医院与拥有高品质保障的国际医疗器械供应商合作，为患者提供全面、个性的奢华美容服务。该医院引进世界各地的整形美容医生，以精湛的技术和自然和谐的审美理念，为求美者带来与众不同的美丽与自信。\n\n三、深圳壹号美都医疗美容门诊部\n深圳天丽医疗美容门诊部是深圳地区一家历史悠久，规模宏大的专业医疗美容机构。中深圳中韩天丽医疗投资管理有限公司投资，总投资额达5000万元人民币，占地面积超过8000平米，堪称深圳的一颗璀璨明珠。作为深圳较早的超五星级整形美容医院，它得到了国家卫生行政部门的严格核准，集教学、科研与临床于一体。早在2010年，它就被评为中国十大具影响力整形机构之一，深受消费者信赖。\n此门诊部拥有宽敞舒适的就诊环境，独立的私密咨询室，并且配备了国际标准的层流净化手术室8间。院内设有多个中心包括整形美容中心、非手术整形美容中心、激光美容中心等，为患者提供全方位的美容服务。\n一、二楼的整形美容中心是深圳与韩国合作的专科机构，拥有技艺高超的中外整形外科专家。这里配备了先进的手术显微镜和共振溶脂系统，开展各种整形美容项目，满足患者的需求。无论是韩式眼部整形、微创无痕隆胸，还是个性化隆鼻\n三点弧线改脸形，都能在这里得到完美的实现。\n三楼激光美容中心引进了国际先进的激光治疗设备，为患者提供高品质的激光美容服务。口腔美容中心也聘请了国内高等口腔教授级专家，为您的口腔健康保驾护航。\n四楼的医疗SPA会所是深圳唯一一家结合手术整形术后保养的场所。这里结合了中国千年的中医学术研究出的美容方式实现了补水、抗衰、祛痘、祛斑、美白等功效。患者可以在这里享受特调的花茶、养颜的甜品，还可以在瑜伽和健身房中放松身心，营造一个轻松舒适的休闲环境。\n\n深圳鹏爱悦己医疗美容门诊部\n深圳鹏爱悦已医疗美容门诊部位于深圳市罗湖区人民南路3023号中旅大厦1-3楼。这是一家提供全方位医疗美容服务的现代化机构，包括双眼皮手术、鼻部手术、面部手术等。这里汇聚了一批经验丰富的医疗美容专家，致力于为患者带来专业的美容服务。\n深圳天丽医疗美容门诊部整形美容价格明细表\n以下是天丽医疗美容门诊部的部分整形美容项目价格\n假体隆胸内窥镜超声刀:1438~4340元\n抽脂肪丰胸:1452~3640元\n复合do胸:1230~4925元\n..以及其他项目\n\n深圳出名整形美容医生介绍\n郭能强医师:擅长丰胸微创手术、鼻孔内切开矫正术等，现任协和医院整形外科副教授，经验丰富。\n梁智医师:擅长隆乳美胸术、假体隆鼻等，作为烧伤整形科主任，他在整形美容领域有着深厚的造诣。这两位医生都在整形美容领域有着卓越的成就和丰富的经验，是患者值得信赖的专家。深圳天丽医疗美容门诊部以其专业、安全、高效的服务，赢得了广大患者的认可和好评，是您实现美丽的佳选择', 1, '2024-12-09 12:49:08');
INSERT INTO `news` VALUES (571, '深圳市上眼睑下垂矫正医院排行合集参考，美莱医院备受好评！', 'http://localhost:8092/file/8c03542a-f28b-471f-91d0-351e2a7992e8.png', '深圳市上眼睑下垂矫正医院排行合集参考，美莱医院备受好评！', '   很多人都不知道大小眼在医学上称为上睑下垂，目前上睑下垂分三个程度：轻度、中度、重度。轻度的上睑下垂一般只会影响形象，中度、重度上睑下垂不仅仅会影响个人形象还会影响视力。所以有大小的朋友一定要重视起来，建议尽早到院做上睑下垂矫正治疗。想做上睑下垂矫正治疗的你是不是不知道医院怎么选择？下文会为大家推荐靠谱整形医院一起去看看！\n\n![07fadbb0ec6f327feb7bdba9a2948de.png](http://localhost:8092/file/e3feb925-cf37-4f00-88aa-1554a00423b9.png)\n\n   深圳美莱医疗美容医院做上睑下垂矫正手术效果不错，深圳美莱于2012年登记成立，开业至今一直拥有良好的口碑。医院设有整形科室开展眼部整形、鼻部整形、隆胸手术、吸脂塑形等整形项目，可以为广大爱美者提供变美服务。深圳美莱医院详细地址：深圳市福田区深南中路2044号，有需要的爱美者可以到院先面诊。\n\n　　在深圳美莱医院做上睑下垂矫正治疗前，美莱整形医生会先面诊求美者，需要根据其眼部形态实际情况设计矫正方案，并安排求美者进行体检预约手术时间。美莱会提供标准手术室进行上睑下垂矫正手术，整个手术过程由经验丰富医护团队根据设计好的矫正方案进行手术，所以术后达到的上睑下垂矫正效果理想。\n\n![961d0f116c83e184451a9509bbf6fc2.png](http://localhost:8092/file/3d135098-8173-4204-9c9e-3e3561442566.png)\n\n做完上睑下垂矫正手术后一般多久可以消肿？\n\n　　在正规医院做了上睑下垂矫正手术后，一般需要3到4周左右眼部才能消肿，具体消肿司机还要以实际恢复情况为准。\n\n　　做了上睑下垂矫正手术后消肿时间是由局部损伤的轻重程度决定，出现了轻微的损伤3三周左右的时间会慢慢好转，损伤比较严重的情况下可能会需要4周左右。如果术后没有做好护理工作发生了炎症，那么就需要更长的时间才能消肿了。因此需要特别注意眼部的护理。在恢复期间尽量不要熬夜，同时还要避免用眼过度。', 1, '2024-12-12 22:40:26');
INSERT INTO `news` VALUES (572, 'OPT美肤', 'http://localhost:8092/file/a11905ec-5838-426a-8b11-d9b880126b62.png', '解决肌肤的多种瑕疵问题，肌肤变得更加的白嫩细滑，有光泽。', '## 基础信息\n**项目优点**\n- 1.效果较明显，疗效更高; \n- 2.可同时治疗色斑、痘痘、痘印、肤色暗沉、皮肤粗糙、毛孔粗大、红血丝等多种问题; \n- 3.所需恢复相对较短。\n\n**项目缺点**\n- 1.价格相对较高。\n- 2.操作不当有烫伤的可能性\n\n**禁忌人群**\n- 1.妊娠期女性;\n- 2.光过敏者、对光敏感者及用过光敏感药物者;\n- 3.高血压、糖尿病患者;\n- 4长期服用某些精神类药物者;\n- 5.服用消炎药、降压药者;\n- 6.2周内有日光曝晒者;面部有炎症者，两周内有日光曝晒者;\n- 7.面部有炎症者。\n\n**适用人群**\n- 1.改善皮肤质地、皱纹、毛孔粗大、色泽晦暗、痘痘、皮肤松弛等。\n- 2,良性的色素性皮肤疾病:崔斑、老年斑、崔斑样痣、咖啡斑、色素异常症、色素沉着、黄福斑、色素斑等。\n- 3.良性的皮肤血管疾病:鲜红斑痣、血管瘤、面部或躯干的毛细血管扩张(红血丝)，酒糟皇、玫瑰座疮、如蛛、Civate皮肤导色症、腹部静脉和静脉畸形等。\n- 4疤痕类病变:痤疮疤痕:外科疤。\n- 5.皮肤纹理:妊娠纹;膨胀纹;萎缩纹;肥胖纹。\n- 6.全身脱毛。\n\n## 使用方式\n|操作时间|恢复时间|间隔周期|\n|-|-|-|\n|10-20分钟|0-7天左右|3-6次，每次间隔1个月|\n|作用周期|操作方式|麻醉方式|\n|1-2个月|光电|无需麻醉|\n\n## 术后及常见问题\n==术前准备==\n- **护理方法：**\n使用外用维A酸药膏或者祛斑产品的人，建议停药1周后开始治疗。\n治疗前2周内不能做激光、磨皮、果酸换肤等美容项目。疗前一个月内避免强烈日晒或做室外SPA。发炎、伤口化脓的皮肤不适合治疗。\n口服维A酸的人，建议停药3个月后再开始治疗。如果有光敏感病史、皮肤病变、免疫系统异常，需要做好跟医生的沟通。\n\n==0天~3天 红肿期==\n- **护理方法：**\n治疗后当天，宜用低温水清洁皮肤，可使用保湿防晒护肤品;治疗后要避免，阳光紫外线直接照射，需要加强防晒，避免晒伤导致色素沉着;禁烟酒及辛辣刺激的食物。\n- **恢复提示：**\n治疗后会出现，短暂的红肿热等反应。\n\n==组织恢复期4天~7天==\n- **护理方法：**\n治疗后一星期内，不能使用含果酸、A酸、水杨酸、去角质、高浓度维他命C、酒精等，刺激性成分的保养品。\n- **恢复提示：**\n红肿反应等基本消退，皮肤恢复正常状态。\n\n==++8天~30天效果显现期++==\n- **护理方法：**\n可以继续完成疗程的治疗，并做好补水防晒的工作，避免晒伤导致色素沉着。\n- **恢复提示：**\n可见效果，慢慢起效，根据个人体质和情况不同，一般3-6次就会有效果。\n', 1, '2024-12-12 23:24:22');

-- ----------------------------
-- Table structure for orders
-- ----------------------------
DROP TABLE IF EXISTS `orders`;
CREATE TABLE `orders`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '订单编号',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户编号',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目编号',
  `order_no` varchar(200) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '订单号',
  `beautician_id` bigint(20) NULL DEFAULT NULL COMMENT '美容师编号',
  `money` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '价格',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态[0:待支付,1:已支付,2:待服务,3:服务中,4:已完成,5:已取消]',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `end_time` datetime(0) NULL DEFAULT NULL COMMENT '完成时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '美容订单' ROW_FORMAT = Dynamic;

