-- ----------------------------
-- Table structure for subscribes
-- ----------------------------
DROP TABLE IF EXISTS `subscribes`;
CREATE TABLE `subscribes`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '预约编号',
  `project_id` bigint(20) NULL DEFAULT NULL COMMENT '项目编号',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户编号',
  `start_time` datetime(0) NULL DEFAULT NULL COMMENT '预约时间',
  `create_time` datetime(0) NULL DEFAULT NULL COMMENT '创建时间',
  `status` int(11) NULL DEFAULT NULL COMMENT '状态[0:预约成功,1:已完成,2:已取消,3:待支付]',
  `order_id` bigint(20) NULL DEFAULT NULL COMMENT '订单ID',
  `bid` bigint(20) NULL DEFAULT NULL COMMENT '美容师',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 34 CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '项目预约' ROW_FORMAT = Dynamic;

